const item = $input.first().json.body || $input.first().json;

const meetingId = item.meetingId || 'AGM-2026';
const meetingTitle = item.title || 'Annual General Body Meeting';
const meetingDate = item.meetingDate || '2026-11-20';
const attendees = item.attendees || ['President', 'Secretary', 'Treasurer', '78 Resident Owners'];
const rawNotes = item.rawNotes || item.transcript || 'Discussion on security agency renewal, clubhouse gym AC replacement budget of 1.2 Lakhs approved, EV charging bay electrical load sanction approved, vendor disputed water tanker rates.';

const prompt = `You are the Official Rapporteur & Governance Secretary for the Mana Residency Society Council.
Process the following raw meeting notes/transcripts into a formal, legal Minutes of Meeting (MoM) dossier:

Meeting Context:
- Meeting: ${meetingTitle} (${meetingId}) on ${meetingDate}
- Key Attendees: ${JSON.stringify(attendees)}
- Discussion Notes / Audio Transcript:
"${rawNotes}"

Extraction Guidelines:
1. Executive Summary: Professional, neutral 2-paragraph overview of assembly proceedings.
2. Formal Resolutions Passed: Clear numbering with vote tally indication (Unanimous / Majority / Dissent noted).
3. Action Items Matrix: Assign concrete task, assigned committee member/owner, deadline, and urgency.
4. Key Grievances & Deferrals: Items deferred to next Extraordinary General Meeting (EGM).

Respond ONLY with a valid JSON object matching this schema:
{
  "executiveSummary": string,
  "resolutions": [
    { "resId": string, "title": string, "verdict": "PASSED_UNANIMOUSLY" | "PASSED_MAJORITY" | "REJECTED" | "DEFERRED", "details": string }
  ],
  "actionItems": [
    { "task": string, "assignedTo": string, "deadline": string, "priority": "HIGH" | "MEDIUM" | "LOW" }
  ],
  "deferredMatters": string[],
  "formalMoMBulletin": string
}`;

return [{ json: { prompt, meetingId, meetingTitle } }];

const gemini = $input.first().json;
let parsed = {};
try {
  const raw = gemini.candidates[0].content.parts[0].text;
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = {
    executiveSummary: "The assembly convened to discuss critical society operations, facility upgrades, and vendor contract renewals.",
    resolutions: [
      { resId: "RES-01", title: "Clubhouse HVAC & Gym Upgrade", verdict: "PASSED_MAJORITY", details: "Allocated ₹1.2 Lakhs from Sinking Fund reserve." }
    ],
    actionItems: [
      { task: "Procure quotation for 3 ton inverter AC", assignedTo: "Facility Manager", deadline: "7 Days", priority: "HIGH" }
    ],
    deferredMatters: ["Water tanker renegotiation pending revised supplier rate card."],
    formalMoMBulletin: "Minutes officially recorded and queued for committee signatures."
  };
}

const meta = $('Prepare AI Prompt').first().json;
return [{ json: { status: "success", meetingId: meta.meetingId, title: meta.meetingTitle, generatedAt: new Date().toISOString(), mom: parsed } }];
